INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 2, 'theory', 'Quiz: variables and types');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 2, 0, 'How should you read the line count = 5?', '["count equals five", "Put the value 5 into the box named count", "Compare count and 5", "Check that count is 5"]', 1, 'The equals sign here is assignment: the right-hand side is evaluated first, then put into the box.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 2, 1, 'Which variable name is not allowed?', '["user_count", "count2", "2count", "_temp"]', 2, 'A name cannot start with a digit. Letters, digits and underscore are fine.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 2, 2, 'Are age and Age one variable or two different ones?', '["One: case does not matter", "Different: case matters", "Python raises an error for similar names", "It depends on the Python version"]', 1, 'Case matters: age and Age are two different boxes.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 2, 3, 'What does len("banana") return?', '["5", "6", "7", "An error: len works only with numbers"]', 1, 'len returns the number of characters in the string, spaces included: here there are six.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 2, 4, 'What happens when "5" + 5 is evaluated?', '["You get 10", "You get \"55\"", "A type error: Python does not guess what you meant", "You get \"5 5\""]', 2, 'A string and a number cannot be added. You need a conversion: int(''5'') + 5 or ''5'' + str(5).');
